sys_script_include.script:
var HoCOHSMPdfReprocessorAjax = Class.create();
HoCOHSMPdfReprocessorAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	getPDFTemplate: function(){
		var case_sys_id = this.getParameter("sysparm_case_sys_id");
		var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
		gr.get(case_sys_id);
		gr.query();
		gr.next();
		return gr.pdf_template;
	},

	reprocessPDF: function(){
		var case_sys_id = this.getParameter("sysparm_case_sys_id");
		var pdf_template = this.getParameter("sysparm_case_pdf_template");
		var file_name = this.getParameter("sysparm_case_file_name");

		var gr = new GlideRecord('x_hccc_hoc_ohs_investigation_case');
		gr.get(case_sys_id);
		gr.query();
		gr.next();
		new x_hccc_hoc_ohs.HoCOHSMPdf().generatePDF(gr, pdf_template, file_name);
		return "";
	},
    type: 'HoCOHSMPdfReprocessorAjax'
});
